(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  const cards = [...document.querySelectorAll('.tb-project-main')];
  out.beforeCount = cards.length;
  (cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0]).click();
  await sleep(3000);
  out.title = document.querySelector('.pj-title')?.textContent || null;

  // 做同款：复制一件新的，原件不动
  [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('做同款')).click();
  await sleep(3000);
  out.afterRemixTitle = document.querySelector('.pj-title')?.textContent || null;
  out.remixDesc = (document.querySelector('.pj-card .pj-text')?.textContent || '').slice(0, 40);

  // 保存作品文件（.ecp）
  [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('保存作品文件')).click();
  await sleep(3000);
  out.exportClicked = true;

  // 返回工具箱
  document.querySelector('.pj-crumb-link').click();
  await sleep(2000);
  out.afterCount = document.querySelectorAll('.tb-project-main').length;
  out.notice = document.querySelector('.tb-ok')?.textContent || null;
  out.listTitles = [...document.querySelectorAll('.tb-project-main')].map((c) => (c.innerText || '').split('\n')[0]).join(' | ');
  out.templates = document.querySelectorAll('.tb-template, .tb-tpl').length;
  return JSON.stringify(out);
})()
